class List(models.Thing):
    """Class to represent /type/list objects in OL."""

    def url(self, suffix="", **params):
        return self.get_url(suffix, **params)

    def get_url_suffix(self):
        return self.name or "unnamed"

    def get_owner(self):
        """Return the user whose key appears in this list's key, if present."""
        match = re.fullmatch(r"(/people/[^/]+)/lists/[^/]+", self.key)
        return self._site.get(match.group(1)) if match else None

    def get_cover(self):
        """Returns a cover object."""
        return self.cover and models.Image(self._site, "b", self.cover)

    def get_tags(self):
        """Returns tags as objects."""
        return [web.storage(name=t, url=self.key + "/tags/" + t) for t in self.tags]

    def _get_subjects(self):
        """Returns list of subjects inferred from the seeds."""
        return [
            web.storage(title="Cheese", url="/subjects/cheese"),
            web.storage(title="San Francisco", url="/subjects/place:san_francisco"),
        ]

    def add_seed(self, seed):
        """Add an author, edition, work, or subject seed if absent."""
        if isinstance(seed, models.Thing):
            seed = {"key": seed.key}

        index = self._index_of_seed(seed)
        if index >= 0:
            return False
        self.seeds = self.seeds or []
        self.seeds.append(seed)
        return True

    def remove_seed(self, seed):
        """Remove a seed from the list if present."""
        if isinstance(seed, models.Thing):
            seed = {"key": seed.key}

        if (index := self._index_of_seed(seed)) >= 0:
            self.seeds.pop(index)
            return True
        return False

    def _index_of_seed(self, seed):
        for i, stored_seed in enumerate(self.seeds):
            if isinstance(stored_seed, models.Thing):
                stored_seed = {"key": stored_seed.key}
            if stored_seed == seed:
                return i
        return -1

    def __repr__(self):
        return f"<List: {self.key} ({self.name!r})>"

    def _get_rawseeds(self):
        def process(seed):
            if isinstance(seed, str):
                return seed
            else:
                return seed.key

        return [process(seed) for seed in self.seeds]

    @cached_property
    def last_update(self):
